using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using Unity.Collections;
public static class RestoreCollarBinding {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string prefab="Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab";const string asset="Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_CollarRestored.asset";Directory.CreateDirectory("Data/EthanV2/CollarReview/Before");if(!File.Exists("Data/EthanV2/CollarReview/Before/Ethan_V2.prefab"))File.Copy(prefab,"Data/EthanV2/CollarReview/Before/Ethan_V2.prefab");
 var root=PrefabUtility.LoadPrefabContents(prefab);try{var all=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var cloth=all.Single(r=>r.name=="BAKED_Outfits_LOD0");var body=all.Single(r=>r.name=="BAKED_body_lod0_mesh");var fbx=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2_73_Baked.fbx");var original=fbx.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name==cloth.name);var originalBones=original.bones.Select(b=>root.transform.Find(AnimationUtility.CalculateTransformPath(b,fbx.transform))).ToArray();if(originalBones.Any(b=>!b))throw new Exception("Missing authored clothing bones");var basis=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_BodyBound.asset");var mesh=UnityEngine.Object.Instantiate(basis);mesh.name="EthanV2_Outfit_CollarRestored";var bones=body.bones.Concat(originalBones).ToArray();int collarBone=Array.FindIndex(body.bones,b=>b.name=="spine_05");if(collarBone<0)throw new Exception("Chest bone missing");mesh.bindposes=bones.Select(b=>b.worldToLocalMatrix*cloth.transform.localToWorldMatrix).ToArray();var counts=new byte[mesh.vertexCount];var weights=new List<BoneWeight1>();var vertices=mesh.vertices;var normals=mesh.normals;int nativeAt=0,baseAt=0,affected=0;
 using(var nc=original.sharedMesh.GetBonesPerVertex())using(var nw=original.sharedMesh.GetAllBoneWeights())using(var bc=basis.GetBonesPerVertex())using(var bw=basis.GetAllBoneWeights()){
 for(int i=0;i<vertices.Length;i++){var point=root.transform.InverseTransformPoint(cloth.transform.TransformPoint(vertices[i]));float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.57f,1.62f,point.y))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.12f,.145f,Mathf.Abs(point.x))));if(blend>.001f)affected++;var combined=new Dictionary<int,float>();for(int j=0;j<bc[i];j++){var w=bw[baseAt++];combined[w.boneIndex]=w.weight*(1-blend);}for(int j=0;j<nc[i];j++){var w=nw[nativeAt++];int bone=body.bones.Length+w.boneIndex;combined[bone]=w.weight*blend;}var kept=combined.Where(w=>w.Value>1e-7f).OrderByDescending(w=>w.Value).ToArray();float sum=kept.Sum(w=>w.Value);counts[i]=(byte)kept.Length;weights.AddRange(kept.Select(w=>new BoneWeight1{boneIndex=w.Key,weight=w.Value/sum}));}}
 using(var c=new NativeArray<byte>(counts,Allocator.Temp))using(var w=new NativeArray<BoneWeight1>(weights.ToArray(),Allocator.Temp))mesh.SetBoneWeights(c,w);
 var existing=AssetDatabase.LoadAssetAtPath<Mesh>(asset);if(existing){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,asset);cloth.sharedMesh=mesh;cloth.bones=bones;cloth.rootBone=root.transform;cloth.quality=SkinQuality.Auto;cloth.localBounds=new Bounds(new Vector3(0,1.1f,0),new Vector3(2.4f,2.4f,2.4f));PrefabUtility.SaveAsPrefabAsset(root,prefab);AssetDatabase.SaveAssets();var result=new{asset,collarVerticesRestored=affected,authoredRigPreserved=true,shirtGeometryUnchanged=mesh.vertices.SequenceEqual(basis.vertices),shirtShapeChannels=mesh.blendShapeCount,boundsCorrected=true};File.WriteAllText("Data/EthanV2/CollarReview/restoration.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
 }finally{PrefabUtility.UnloadPrefabContents(root);}}
}
